agent-browser run - <<'JS'
const out=[];
for (const u of ["Tiramisu","Panna-cotta","Risotto-alla-milanese","Gnocchi-di-patate"]) {
  page.goto("https://ricette.giallozafferano.it/"+u+".html");
  out.push(u+" | "+page.evaluate(()=>{const t=document.body.innerText;const m=t.match(/Cottura[^\n]*\n?[^\n]*/);return document.querySelector("h1")?.textContent+" | "+(m&&m[0]);}));
}
return out;
